class CatalogService {
  late BehaviorContext behaviors;
  int offset = 0;

  Future<Object?> page(@PageDefaults({"defaultSize":20,"maxSize":100,"sort":["id"]}) Map<String, Object?> input) async {
    return input['offset'];
  }

  @OnStart
  Future<void> initialize() async {
