#[Service]
struct CatalogService {
    behaviors: BehaviorContext,
    offset: f64,
}

impl CatalogService {
    fn new() -> Self {
        let options = BehaviorOptions::new("public-catalog", BehaviorSignal::new());
        Self { behaviors: Behaviors::create::<ApplicationSetup>(options).expect("behavior context"), offset: 0.0 }
    }

    fn page(&self, #[PageDefaults({"defaultSize":20,"maxSize":100,"sort":["id"]})] input: BehaviorValue) -> BehaviorResult<BehaviorValue> {
        Ok(input.get("offset").cloned().unwrap_or(BehaviorValue::Null))
    }

    #[OnStart]
    fn initialize(&mut self) {
        let first = BehaviorValue::object([("page", BehaviorValue::Number(1.0))]);
        self.offset = Self::offset_of(self.page(first));
    }

    fn offset_of(value: BehaviorResult<BehaviorValue>) -> f64 {
        match value {
            Ok(BehaviorValue::Number(offset)) => offset,
            _ => 0.0,
        }
    }
}

import "errors"

// @Service
type CatalogService struct {
	behaviors *BehaviorContext
	Offset    int64
}

func (catalog *CatalogService) Page(
	// @PageDefaults({"defaultSize":20,"maxSize":100,"sort":["id"]})
	input BehaviorValue,
) (BehaviorValue, error) {
	return input.(map[string]any)["offset"], nil
}

// @OnStart
func (catalog *CatalogService) Initialize() error {
	context, err := BehaviorsCreate[ApplicationSetup](NewBehaviorOptions("public-catalog", NewBehaviorSignal()))
	catalog.behaviors = context
	offset, pageErr := catalog.Page(map[string]any{"page": 1})
	catalog.Offset = catalog.offsetOf(offset)
	return errors.Join(err, pageErr)
}

func (catalog *CatalogService) offsetOf(value BehaviorValue) int64 {
	number, _ := value.(float64)
	return int64(number)
}

@Service
final class CatalogService {
    var behaviors: BehaviorContext!
    var offset: Int = 0

    func page(@PageDefaults({"defaultSize":20,"maxSize":100,"sort":["id"]}) _ input: BehaviorJSON) throws -> BehaviorJSON {
        input.get("offset")
    }

    @OnStart
    func initialize() {
        behaviors = try? Behaviors.create(ApplicationSetup.self, partition: "public-catalog", signal: BehaviorSignal())
        offset = offsetOf(try? page(.object(["page": .number(1)])))
    }

    private func offsetOf(_ value: BehaviorJSON?) -> Int {
        guard case .number(let number)? = value else { return 0 }
        return Int(number)
    }
}

