@Service
export default class ReportService {
  /** @type {TacWindowControls} */
  @Needs
  windowControls;
  problem = '';

  minimize() {
    this._keepProblem(() => this.windowControls.minimize());
  }

  resize() {
    this._keepProblem(() => this.windowControls.resize(1280, 800));
  }

  rename() {
    this._keepProblem(() => this.windowControls.setTitle('Quarterly report'));
  }

  /** @param {() => void} call */
  _keepProblem(call) {
    try {
      call();
    } catch (refusal) {
      this.problem = /** @type {Error} */ (refusal).message;
    }
  }
}

@Service
export default class ReportService {
  @Needs
  windowControls!: TacWindowControls;
  problem = '';

  minimize(): void {
    this.keepProblem(() => this.windowControls.minimize());
  }

  resize(): void {
    this.keepProblem(() => this.windowControls.resize(1280, 800));
  }

  rename(): void {
    this.keepProblem(() => this.windowControls.setTitle('Quarterly report'));
  }

  private keepProblem(call: () => void): void {
    try {
      call();
    } catch (refusal) {
      this.problem = (refusal as Error).message;
    }
  }
}

// @Service
type ReportService struct {
	// @Needs
	windowControls WindowControls
	Problem        string
}

func (report *ReportService) Minimize() {
	report.keepProblem(report.windowControls.Minimize())
}

func (report *ReportService) Resize() {
	report.keepProblem(report.windowControls.Resize(1280, 800))
}

func (report *ReportService) Rename() {
	report.keepProblem(report.windowControls.SetTitle("Quarterly report"))
}

func (report *ReportService) keepProblem(problem error) {
	if problem != nil {
		report.Problem = problem.Error()
	}
}

@Service
class ReportService {
    private val windowControls = WindowControls()
    var problem: String = ""

    fun minimize() {
        keepProblem { windowControls.minimize() }
    }

    fun resize() {
        keepProblem { windowControls.resize(1280, 800) }
    }

    fun rename() {
        keepProblem { windowControls.setTitle("Quarterly report") }
    }

    private fun keepProblem(call: () -> Unit) {
        try {
            call()
        } catch (refusal: IllegalStateException) {
            problem = refusal.message.orEmpty()
        }
    }
}

@Service
class ReportService {
    private final WindowControls windowControls = new WindowControls();
    String problem = "";

    void minimize() {
        keepProblem(windowControls::minimize);
    }

    void resize() {
        keepProblem(() -> windowControls.resize(1280, 800));
    }

    void rename() {
        keepProblem(() -> windowControls.setTitle("Quarterly report"));
    }

    private void keepProblem(Runnable call) {
        try {
            call.run();
        } catch (IllegalStateException refusal) {
            problem = refusal.getMessage();
        }
    }
}

