@Service
final class ReportService {
    private let windowControls = WindowControls()
    var problem: String = ""

    func minimize() {
        keepProblem { try windowControls.minimize() }
    }

    func resize() {
        keepProblem { try windowControls.resize(width: 1280, height: 800) }
    }

    func rename() {
        keepProblem { try windowControls.setTitle("Quarterly report") }
    }

    private func keepProblem(_ call: () throws -> Void) {
        do {
            try call()
        } catch {
            problem = String(describing: error)
        }
    }
}

#[Service]
#[derive(Default)]
struct ReportService {
    window_controls: WindowControls,
    problem: String,
}

impl ReportService {
    fn minimize(&mut self) {
        self.problem = self.window_controls.minimize().err().unwrap_or_default();
    }

    fn resize(&mut self) {
        self.problem = self.window_controls.resize(1280, 800).err().unwrap_or_default();
    }

    fn rename(&mut self) {
        self.problem = self.window_controls.set_title("Quarterly report").err().unwrap_or_default();
    }
}

[Service]
public class ReportService
{
    private readonly WindowControls windowControls = new();
    public string Problem = "";

    public void Minimize() => KeepProblem(windowControls.Minimize);

    public void Resize() => KeepProblem(() => windowControls.Resize(1280, 800));

    public void Rename() => KeepProblem(() => windowControls.SetTitle("Quarterly report"));

    private void KeepProblem(Action call)
    {
        try { call(); }
        catch (InvalidOperationException refusal) { Problem = refusal.Message; }
    }
}

